import { test, expect } from '@playwright/test';

test.describe('Table Row Filtering', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should display filtered results when typing in the search input', async ({ page }) => {
    const searchInput = page.getByLabel('Search'); // Replace with the actual label of the search input
    await searchInput.fill('Test Item'); // Replace with the actual search term

    const filteredRow = page.getByText('Test Item'); // Replace with the actual text of the expected row
    await expect(filteredRow).toBeVisible();
  });

  test('should show no results for non-matching search term', async ({ page }) => {
    const searchInput = page.getByLabel('Search'); // Replace with the actual label of the search input
    await searchInput.fill('Non-existing Item'); // Replace with a term that does not exist

    const noResultsMessage = page.getByText('No results found'); // Replace with the actual no results message
    await expect(noResultsMessage).toBeVisible();
  });
});
